 public async Task<HttpClient> Client(Guid? actor=null){Host??=new Factory(AllowUnscannedUploads);var c=Host.CreateClient(new(){BaseAddress=new Uri("https://localhost"),AllowAutoRedirect=false,HandleCookies=true});if(actor!=null){await using var db=Db();var email=await db.Users.Where(u=>u.Id==actor).Select(u=>u.Email).SingleAsync();var token=await Token(c,"/TaiKhoan/DangNhap");using var r=await c.PostAsync("/TaiKhoan/DangNhap",new FormUrlEncodedContent(new Dictionary<string,string>{{"Email",email!},{"MatKhau",Password},{"__RequestVerificationToken",token}}));Assert.Equal(HttpStatusCode.Redirect,r.StatusCode);}return c;}
 public static async Task<string> Token(HttpClient c,string url){var had=c.DefaultRequestHeaders.TryGetValues("X-Requested-With",out var values);var saved=values?.ToArray();c.DefaultRequestHeaders.Remove("X-Requested-With");try{for(int i=0;i<4;i++){using var r=await c.GetAsync(url);if((int)r.StatusCode is 301 or 302 or 303){var location=r.Headers.Location!.OriginalString;Assert.StartsWith("/",location);Assert.False(location.StartsWith("//"));url=location;continue;}var body=await r.Content.ReadAsStringAsync();Assert.Equal(HttpStatusCode.OK,r.StatusCode);var m=Regex.Match(body,"name=\"__RequestVerificationToken\"[^>]*value=\"([^\"]+)\"");Assert.True(m.Success,"CSRF not found: "+url);return WebUtility.HtmlDecode(m.Groups[1].Value);}throw new Exception("CSRF redirect loop");}finally{if(had)c.DefaultRequestHeaders.TryAddWithoutValidation("X-Requested-With",saved);}}
 public async Task<HttpResponseMessage> Post(HttpClient c,string url,Dictionary<string,string> fields,string form="/TaiKhoan/DangNhap",bool csrf=true,bool ajax=true){if(csrf)fields["__RequestVerificationToken"]=await Token(c,form);c.DefaultRequestHeaders.Remove("X-Requested-With");if(ajax)c.DefaultRequestHeaders.TryAddWithoutValidation("X-Requested-With","XMLHttpRequest");var r=await c.PostAsync(url,new FormUrlEncodedContent(fields));await Record(r);return r;}
